import { dailyIndex } from "@/lib/daily";
import { distanceKm, type LatLon } from "@/lib/geo";
import type { Localized } from "@/lib/i18n";
import data from "./data/journeys.json";

// data/journeys.json is generated by scripts/fetch-journeys.mjs — don't edit
// it by hand; draw or fix routes in scripts/journeys-roster.mjs instead.

export type Mode = "sea" | "land" | "air" | "river" | "mixed";

/** A point on the route. Named stops get a dot and a label on the map. */
export type Stop = LatLon & { name?: Localized };

export type Journey = {
  id: string;
  name: Localized;
  /** Years it began and ended; negative for BC. */
  start: number;
  end: number;
  mode: Mode;
  stops: Stop[];
  extract: { en: string; pt: string | null };
  wiki: { en: string; pt: string | null };
};

export const JOURNEYS = data as Journey[];

const byId = new Map(JOURNEYS.map((journey) => [journey.id, journey]));

export const journeyById = (id: string): Journey | undefined => byId.get(id);

const fold = (text: string) =>
  text
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLowerCase();

/** The words of a journey's names that would give it away on the map ("Magellan", "Livingstone"). */
export function telltaleWords(journey: Journey): string[] {
  const small = new Set(["the", "and", "from", "with", "para", "pela", "pelo", "first", "primeira", "primeiro", "great", "grande", "voyage", "viagem", "expedition", "expedição", "route", "rota", "journey", "jornada", "march", "marcha", "crossing", "travessia", "descent", "descida", "pilgrimage", "peregrinação", "circumnavigation", "navegação"].map(fold));
  return [
    ...new Set(
      [journey.name.en, journey.name.pt]
        .flatMap((name) => fold(name).split(/[^\p{L}\p{N}]+/u))
        .filter((word) => word.length >= 4 && !small.has(word)),
    ),
  ];
}

/**
 * A stop's label while the journey is still a mystery: its name, unless the
 * name gives the journey away (the Strait of Magellan on Magellan's voyage).
 * Once the puzzle is over every stop shows its full name.
 */
export function stopLabelInPlay(stop: Stop, journey: Journey, locale: keyof Localized): string | undefined {
  const name = stop.name?.[locale];
  if (!name) return undefined;
  const words = fold(name).split(/[^\p{L}\p{N}]+/u);
  return telltaleWords(journey).some((word) => words.includes(word)) ? "?" : name;
}

export function journeyForDay(day: number): Journey {
  return JOURNEYS[dailyIndex(JOURNEYS.length, day, "wayfarer")];
}

// Longitude difference going the short way round the globe.
const lonDelta = (from: number, to: number) => ((((to - from) % 360) + 540) % 360) - 180;

/** Kilometres travelled on arrival at each stop. */
function milestones(stops: Stop[]): number[] {
  const marks = [0];
  for (let i = 1; i < stops.length; i++) {
    marks.push(marks[i - 1] + distanceKm(stops[i - 1], stops[i]));
  }
  return marks;
}

function pointAt(stops: Stop[], marks: number[], km: number): LatLon {
  const next = marks.findIndex((mark, i) => i > 0 && mark >= km);
  if (next === -1) return stops[stops.length - 1];
  const from = stops[next - 1];
  const to = stops[next];
  const span = marks[next] - marks[next - 1];
  const t = span > 0 ? (km - marks[next - 1]) / span : 0;
  return {
    lat: from.lat + (to.lat - from.lat) * t,
    lon: from.lon + lonDelta(from.lon, to.lon) * t,
  };
}

/** The stretch of the route between two fractions (0–1) of its length. */
export function routeSlice(stops: Stop[], from: number, to: number): LatLon[] {
  const marks = milestones(stops);
  const total = marks[marks.length - 1];
  const start = from * total;
  const end = to * total;
  return [
    pointAt(stops, marks, start),
    ...stops.filter((_, i) => marks[i] > start && marks[i] < end),
    pointAt(stops, marks, end),
  ];
}

/** The stops reached within the first `fraction` of the route. */
export function stopsWithin(stops: Stop[], fraction: number): Stop[] {
  const marks = milestones(stops);
  const end = fraction * marks[marks.length - 1];
  return stops.filter((_, i) => marks[i] <= end + 1e-6);
}
